else:
    print(f'OK: direct edge getWeather->checkTemperature: {direct[0][\"id\"]}')

# Check decision expression
decision = next(n for n in flow['nodes'] if n['id'] == 'checkTemperature')
expr = decision['inputs']['expression']
if 'getWeather.output.body.current.temperature_2m' in expr:
    print(f'OK: decision expression uses HTTP response: {expr}')
else:
    errors.append(f'FAIL: decision expression still references formatSummary: {expr}')

# Check end node outputs
for end_id in ['endNiceDay', 'endBringJacket']:
    end = next(n for n in flow['nodes'] if n['id'] == end_id)
    expr = end['outputs']['summary']['source']['expression']
    if 'getWeather.output.body.current.temperature_2m' in expr and 'formatSummary' not in expr:
        print(f'OK: {end_id} uses HTTP response directly')
    else:
        errors.append(f'FAIL: {end_id} expression wrong: {expr}')

# Check formatSummary gone from variables
var_ids = [v['id'] for v in flow['variables']['nodes']]
if any('formatSummary' in v for v in var_ids):
    errors.append('FAIL: formatSummary still in variables.nodes')
else:
    print('OK: formatSummary not in variables.nodes')

# Check layout has no formatSummary
if 'formatSummary' in flow['layout']['nodes']:
    errors.append('FAIL: formatSummary still in layout.nodes')
else:
    print('OK: formatSummary not in layout.nodes')

# Edge count
print(f'OK: total edges = {len(flow[\"edges\"])} (expected 4)')

if errors:
    print()
    for e in errors:
        print(e)
    sys.exit(1)
else:
    print()
    print('ALL CHECKS PASSED')
